--- a/picosoc/simpleuart.v
+++ b/picosoc/simpleuart.v
@@ -118,8 +118,8 @@
 		end else begin
 			if (send_dummy && !send_bitcnt) begin
-				send_pattern <= ~1;
+				send_pattern <= ~0;
 				send_bitcnt <= 15;
 				send_divcnt <= 0;
 				send_dummy <= 0;
 			end else
 			if (reg_dat_we && !send_bitcnt) begin
", "expected": "tohost PASS replacing FAIL 0xdead, no TRAP uart data mismatch, loopback 0xa5 matched"}

